import axios from 'axios';

const API_URL = 'http://localhost:5000/api/places';

export const fetchPlaces = async (filters) => {
    try {
        const response = await axios.get(API_URL, { params: filters });
        return response.data;
    } catch (error) {
        console.error('Error fetching places:', error);
        throw error;
    }
};

const fetchPlace = async () => {
    try {
        const data = await fetchItemById(id);
        setPlace(data); // Corrected to setPlace instead of setItem
        setError(null);
        setTotalPrice(parseFloat(data.price.slice(1)));
    } catch (error) {
        setError('Item not found or an error occurred while fetching data.');
        console.error('Error fetching item:', error);
    } finally {
        setLoading(false);
    }
};
